def fizzbuzz(n):
    # Genera la lista de strings
    resultado = []
    for i in range(1, n + 1):
        # Verifica si es múltiplo de 3 y 5
        if i % 3 == 0 and i % 5 == 0:
            resultado.append('FizzBuzz')
        # Verifica si es múltiplo de 3
        elif i % 3 == 0:
            resultado.append('Fizz')
        # Verifica si es múltiplo de 5
        elif i % 5 == 0:
            resultado.append('Buzz')
        # Si no es múltiplo de ninguno
        else:
            resultado.append(str(i))
    return resultado

def aplanar(lista):
    # Inicializa la lista plana
    plana = []
    # Itera sobre cada elemento de la lista de entrada
    for elemento in lista:
        # Si el elemento es una lista, llama recursivamente a aplanar y extiende la lista plana
        if isinstance(elemento, list):
            plana.extend(aplanar(elemento))
        # Si el elemento no es una lista, lo añade a la lista plana
        else:
            plana.append(elemento)
    # Devuelve la lista plana resultante
    return plana

def agrupar_por(items, clave):
    # Inicializa el diccionario de resultados
    resultado = {}
    # Itera sobre cada ítem en la lista
    for item in items:
        # Obtiene el valor de la clave
        valor_clave = item[clave]
        # Si el valor no está en el resultado, crea una lista para él
        if valor_clave not in resultado:
            resultado[valor_clave] = []
        # Agrega el ítem a la lista correspondiente
        resultado[valor_clave].append(item)
    return resultado

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    if n < 0:
        n = len(lista) + n
    return lista[-n:] + lista[:-n]

def from_romano(s):
    """Convierte un número romano a entero."""
    roman_map = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev_value = 0
    for char in reversed(s):
        value = roman_map[char]
        if value < prev_value:
            total -= value
        else:
            total += value
        prev_value = value
    return total

def mayor_racha(lista):
    if not lista:
        return None

    max_racha = (lista[0], 0)
    actual_racha = (lista[0], 1)

    for i in range(1, len(lista)):
        if lista[i] == actual_racha[0]:
            actual_racha = (lista[i], actual_racha[1] + 1)
        else:
            if actual_racha[1] > max_racha[1]:
                max_racha = actual_racha
            actual_racha = (lista[i], 1)

    if actual_racha[1] > max_racha[1]:
        max_racha = actual_racha

    return max_racha

