import re

def a_snake(s):
    # Reemplaza mayúsculas seguidas de minúsculas con _minúscula
    s = re.sub(r'(?<!^)(?=[A-Z])', '_', s)
    # Convierte todo a minúsculas
    return s.lower()

def primos(n):
    if n < 2:
        return []
    primos_lista = []
    for num in range(2, n + 1):
        es_primo = True
        for i in range(2, int(num**0.5) + 1):
            if num % i == 0:
                es_primo = False
                break
        if es_primo:
            primos_lista.append(num)
    return primos_lista

def mcd(a, b):
    # Algoritmo de Euclides
    while b:
        a, b = b, a % b
    return a

