    compressed = []
    count = 1
    current_char = s[0]

    for i in range(1, len(s)):
        if s[i] == current_char:
            count += 1
        else:
            compressed.append(current_char + str(count))
            current_char = s[i]
            count = 1

    compressed.append(current_char + str(count))

    compressed_str = "".join(compressed)

    if len(compressed_str) < len(s):
        return compressed_str
    else:
        return s

def balanceado(s):
    stack = []
    mapping = {")": "(", "]": "[", "}": "{"}
    for char in s:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack:
                return False
            top_element = stack.pop()
            if mapping[char] != top_element:
                return False
    return not stack

def transpuesta(m):
    if not m:
        return []
    num_filas = len(m)
    num_columnas = len(m[0])
    transpuesta_m = [[0 for _ in range(num_filas)] for _ in range(num_columnas)]
    for i in range(num_filas):
        for j in range(num_columnas):
            transpuesta_m[j][i] = m[i][j]
    return transpuesta_m

