def contar_islas(grid):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False for _ in range(cols)] for _ in range(rows)]
    count = 0

    def dfs(r, c):
        if r < 0 or r >= rows or c < 0 or c >= cols or visited[r][c] or grid[r][c] == 0:
            return
        visited[r][c] = True
        dfs(r + 1, c)
        dfs(r - 1, c)
        dfs(r, c + 1)
        dfs(r, c - 1)

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and not visited[r][c]:
                count += 1
                dfs(r, c)
    return count

def distancia(a, b):
    # Inicializar la matriz de distancias
    m = len(a)
    n = len(b)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Llenar la primera fila y columna
    for i in range(m + 1):
        dp[i][0] = i
    for j in range(n + 1):
        dp[0][j] = j

    # Llenar la matriz
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            dp[i][j] = min(
                dp[i - 1][j] + 1,        # Borrar
                dp[i][j - 1] + 1,        # Insertar
                dp[i - 1][j - 1] + cost  # Sustituir/Coincidir
            )

    return dp[m][n]

import re

def validar_password(p):
    # Verificar longitud mínima
    if len(p) < 8:
        return False
    # Verificar al menos una mayúscula
    if not re.search(r"[A-Z]", p):
        return False
    # Verificar al menos una minúscula
    if not re.search(r"[a-z]", p):
        return False
    # Verificar al menos un dígito
    if not re.search(r"\d", p):
        return False
    # Verificar al menos un carácter no alfanumérico
    if not re.search(r"[^a-zA-Z0-9]", p):
        return False
    return True

def a_base(n, base):
    if n == 0:
        return '0'
    digitos = "0123456789abcdef"
    resultado = ""
    while n > 0:
        resto = n % base
        resultado = digitos[resto] + resultado
        n //= base
    return resultado

def campo_csv(s):
    # Verificar si el campo necesita ser encerrado en comillas
    if ',' in s or '"' in s or '\n' in s:
        # Duplicar comillas internas y encerrar en comillas dobles
        return f'"{s.replace("\"", "\"\"")}"'
    else:
        # Devolver tal cual si no contiene caracteres especiales
        return s

def titular(s):
    palabras = s.lower().split()
    resultado = []
    preposiciones_excluidas = {'de', 'del', 'la', 'las', 'el', 'los', 'y'}
    for i, palabra in enumerate(palabras):
        if i == 0 or palabra not in preposiciones_excluidas:
            palabra_titulada = palabra[0].upper() + palabra[1:].lower()
        else:
            palabra_titulada = palabra
        resultado.append(palabra_titulada)
    return " ".join(resultado)

def aplanar_hasta(lista, profundidad):
    # Si la profundidad es 0, devuelve la lista sin modificar
    if profundidad == 0:
        return lista[:]

    resultado = []
    for elemento in lista:
        if isinstance(elemento, list) and profundidad > 0:
            # Si es una lista y aún hay profundidad, llama recursivamente
            resultado.extend(aplanar_hasta(elemento, profundidad - 1))
        else:
            # Si no es lista o la profundidad es 0, añade el elemento
            resultado.append(elemento)
    return resultado

def romano_a_int(romano):
    """Convierte un número romano a entero."""
    mapa = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    i = 0
    while i < len(romano):
        siguiente_valor = mapa[romano[i]]
        if i + 1 < len(romano):
            siguiente_valor_next = mapa[romano[i+1]]
            if siguiente_valor < siguiente_valor_next:
                total += siguiente_valor_next - siguiente_valor
                i += 2
                continue
        total += siguiente_valor
        i += 1
    return total

def int_a_romano(n):
    """Convierte un entero a número romano."""
    mapa_valores = {
        1000: 'M', 900: 'CM', 500: 'D', 400: 'CD', 100: 'C', 90: 'XC', 50: 'L', 40: 'XL', 10: 'X', 9: 'IX', 5: 'V', 4: 'IV', 1: 'I'
    }
    romano = ""
    for valor, simbolo in mapa_valores.items():
        while n >= valor:
            romano += simbolo
            n -= valor
    return romano

def sumar_romanos(a, b):
    """Suma dos números romanos y devuelve el resultado en romano."""
    num_a = romano_a_int(a)
    num_b = romano_a_int(b)
    suma = num_a + num_b
    return int_a_romano(suma)

def atender(tareas):
    # Ordenar por prioridad (primer elemento de la tupla)
    return [nombre for prioridad, nombre in sorted(tareas, key=lambda x: x[0])]

def obtener(d, camino, defecto=None):
    # Iterar sobre cada parte del camino
    for clave in camino.split('.'):
        # Verificar si la clave existe en el diccionario actual
        if isinstance(d, dict) and clave in d:
            d = d[clave]
        else:
            # Si no existe o no es un diccionario, devolver el valor por defecto
            return defecto
    # Devolver el valor encontrado al final del camino
    return d

def con_reintentos(fn, veces):
    # Bucle para intentar la función hasta 'veces' veces
    for i in range(veces):
        try:
            # Ejecutar la función
            return fn()
        except Exception as e:
            # Si falla, y no es el último intento, esperar y continuar
            if i < veces - 1:
                continue
            # Si es el último intento, relanzar la excepción
            raise e
